-- SQL Migration script

SET @sStorageEngine = (SELECT `value` FROM `sys_options` WHERE `name` = 'sys_storage_default');

-- Schema changes. Added columns and indexes are applied in script.php after this file.
ALTER TABLE `sys_accounts` MODIFY `receive_news` tinyint(4) NOT NULL DEFAULT '0';

-- New tables
-- Migrations ledger. Same definition as BxDolMigrationsQuery::createLedger().
CREATE TABLE IF NOT EXISTS `sys_migrations` (
  `module` varchar(32) NOT NULL default '',
  `id` varchar(128) NOT NULL,
  `scope` varchar(16) NOT NULL default '',
  `type` varchar(8) NOT NULL default '',
  `checksum` char(64) NOT NULL default '',
  `status` varchar(16) NOT NULL default '',
  `applied` int(11) unsigned NOT NULL default '0',
  `attempted` int(11) unsigned NOT NULL default '0',
  `error` text NOT NULL,
  PRIMARY KEY (`module`, `id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- sys_options
UPDATE `sys_options` SET `extra` = 'stable,beta,dev' WHERE `name` = 'sys_upgrade_channel' AND `extra` = 'stable,beta';
UPDATE `sys_options` SET `value` = '' WHERE `name` = 'sys_site_logo_alt' AND `value` = '0';
UPDATE `sys_options` SET `value` = 'sys_sockets_soketi' WHERE `name` = 'sys_sockets_type' AND `value` = 'sys_soketi';

-- Site logo and mark variants, splash per app (web, iOS, Android).
-- sys_options has a unique key on the name, so INSERT IGNORE adds each option once and keeps an admin's own value.
SET @iCategoryId = (SELECT `id` FROM `sys_options_categories` WHERE `name` = 'system' LIMIT 1);
INSERT IGNORE INTO `sys_options` (`category_id`, `name`, `caption`, `value`, `type`, `extra`, `check`, `check_error`, `order`) VALUES
(@iCategoryId, 'sys_site_logo_dark', '', '0', 'digit', '', '', '', 23),
(@iCategoryId, 'sys_site_logo_inline', '', '', 'text', '', '', '', 23),
(@iCategoryId, 'sys_site_mark', '', '0', 'digit', '', '', '', 24),
(@iCategoryId, 'sys_site_mark_dark', '', '0', 'digit', '', '', '', 24),
(@iCategoryId, 'sys_site_mark_inline', '', '', 'text', '', '', '', 24),
(@iCategoryId, 'sys_site_splash_web_enabled', '', '', 'checkbox', '', '', '', 26),
(@iCategoryId, 'sys_site_splash_ios_enabled', '', '', 'checkbox', '', '', '', 26),
(@iCategoryId, 'sys_site_splash_android_enabled', '', '', 'checkbox', '', '', '', 26),
(@iCategoryId, 'sys_site_splash_code_web', '', '', 'text', '', '', '', 26),
(@iCategoryId, 'sys_site_splash_code_ios', '', '', 'text', '', '', '', 26),
(@iCategoryId, 'sys_site_splash_code_android', '', '', 'text', '', '', '', 26);

