-- Default splash code: only a site that still has the RC3 default gets the new one, code an operator changed is left as it is.
UPDATE `sys_options` SET `value` = '<style>\r\n    /* Guest splash, laid out like the built-in splash of the apps. The colours follow the light and dark scheme.\r\n       The apps leave out what has data-site-only (they draw their own header and footer); the web app puts the\r\n       code in .neo-splash, between its header and footer. */\r\n    .bx-landing {\r\n        --bx-landing-muted: #e4e4e7;\r\n        --bx-landing-accent: #dbeafe;\r\n        --bx-landing-accent-fg: #1d4ed8;\r\n        --bx-landing-primary: #2563eb;\r\n        --bx-landing-title: #0a0a0c;\r\n        --bx-landing-text: #52525b;\r\n        --bx-landing-border: #e4e4e7;\r\n        display: flex;\r\n        flex-direction: column;\r\n        min-height: 100vh;\r\n    }\r\n    .dark .bx-landing,\r\n    [data-theme="dark"] .bx-landing {\r\n        --bx-landing-muted: #3f3f46;\r\n        --bx-landing-accent: #172554;\r\n        --bx-landing-accent-fg: #60a5fa;\r\n        --bx-landing-title: #fafafc;\r\n        --bx-landing-text: #a1a1aa;\r\n        --bx-landing-border: #3f3f46;\r\n    }\r\n    @media (prefers-color-scheme: dark) {\r\n        :root:not([data-theme="light"]) .neo-splash .bx-landing {\r\n            --bx-landing-muted: #3f3f46;\r\n            --bx-landing-accent: #172554;\r\n            --bx-landing-accent-fg: #60a5fa;\r\n            --bx-landing-title: #fafafc;\r\n            --bx-landing-text: #a1a1aa;\r\n            --bx-landing-border: #3f3f46;\r\n        }\r\n    }\r\n    .neo-splash .bx-landing {\r\n        flex: 1 1 auto;\r\n        min-height: 0;\r\n    }\r\n    .bx-landing-header,\r\n    .bx-landing-footer {\r\n        display: flex;\r\n        flex-wrap: wrap;\r\n        align-items: center;\r\n        justify-content: space-between;\r\n        gap: 0.75rem;\r\n        padding: 0.75rem 1rem;\r\n    }\r\n    .bx-landing-header {\r\n        min-height: 4rem;\r\n        box-sizing: border-box;\r\n    }\r\n    .bx-landing-footer {\r\n        border-top: 1px solid var(--bx-landing-border);\r\n        color: var(--bx-landing-text);\r\n        font-size: 0.875rem;\r\n    }\r\n    .bx-landing-main {\r\n        display: flex;\r\n        flex: 1 1 auto;\r\n        flex-direction: column;\r\n        align-items: center;\r\n        justify-content: center;\r\n        gap: 1.5rem;\r\n        box-sizing: border-box;\r\n        width: 100%;\r\n        max-width: 88rem;\r\n        margin: 0 auto;\r\n        padding: 1rem;\r\n    }\r\n    .bx-landing-intro {\r\n        display: flex;\r\n        flex: 1 1 auto;\r\n        flex-direction: column;\r\n        align-items: center;\r\n        gap: 1.5rem;\r\n        width: 100%;\r\n        text-align: center;\r\n    }\r\n    .bx-landing-art {\r\n        display: block;\r\n        width: 12rem;\r\n        height: 12rem;\r\n    }\r\n    .bx-landing-title {\r\n        margin: 0;\r\n        color: var(--bx-landing-title);\r\n        font-size: 2.25rem;\r\n        font-weight: 700;\r\n        line-height: 1.25;\r\n        letter-spacing: -0.025em;\r\n        text-wrap: balance;\r\n    }\r\n    .bx-landing-text {\r\n        max-width: 48rem;\r\n        margin: 0;\r\n        color: var(--bx-landing-text);\r\n        font-size: 1rem;\r\n        line-height: 1.5rem;\r\n        text-wrap: pretty;\r\n    }\r\n    .bx-landing-auth {\r\n        flex: none;\r\n        width: 100%;\r\n        max-width: 28rem;\r\n    }\r\n    .bx-landing-links {\r\n        display: flex;\r\n        flex-wrap: wrap;\r\n        gap: 1rem;\r\n    }\r\n    @media (min-width: 640px) {\r\n        .bx-landing-main { padding: 1.5rem; }\r\n        .bx-landing-text { font-size: 1.125rem; line-height: 1.75rem; }\r\n    }\r\n    @media (min-width: 1024px) {\r\n        .bx-landing-main {\r\n            flex-direction: row;\r\n            gap: 3rem;\r\n            padding: 3rem;\r\n        }\r\n        .bx-landing-intro {\r\n            align-items: flex-start;\r\n            text-align: start;\r\n        }\r\n    }\r\n    @media (min-width: 1280px) {\r\n        .bx-landing-title { font-size: 3rem; }\r\n    }\r\n</style>\r\n<div class="bx-landing bx-def-color-bg-page">\r\n    <header class="bx-landing-header" data-site-only>\r\n        __logo__\r\n        <a class="bx-btn bx-btn-primary" href="__join_link__"><bx_text:_sys_txt_splash_join /></a>\r\n    </header>\r\n    <main class="bx-landing-main">\r\n        <div class="bx-landing-intro text-center">\r\n            __illustration__\r\n            <h1 class="bx-landing-title"><bx_text:_sys_txt_splash_title /></h1>\r\n            <p class="bx-landing-text"><bx_text:_sys_txt_splash_slogan /></p>\r\n        </div>\r\n        <div class="bx-landing-auth">__login_form_in_box__</div>\r\n    </main>\r\n    <footer class="bx-landing-footer" data-site-only>\r\n        <nav class="bx-landing-links">\r\n            <a href="<bx_url_root />page.php?i=terms"><bx_text:_sys_menu_item_title_terms /></a>\r\n            <a href="<bx_url_root />page.php?i=privacy"><bx_text:_sys_menu_item_title_privacy /></a>\r\n        </nav>\r\n        <span>&copy; {site_title}</span>\r\n    </footer>\r\n</div>' WHERE `name` = 'sys_site_splash_code' AND REPLACE(`value`, '\r', '') = REPLACE('<style>\r\n    /*--- Splash ---*/\r\n  	.bx-page {\r\n        position: relative;\r\n  	}\r\n	.bx-header {\r\n        position: relative;\r\n      	display: -webkit-flex;\r\n        display: flex;\r\n        -webkit-align-items: center;\r\n        align-items: center;\r\n      	justify-content: center;\r\n      	-webkit-justify-content: center;\r\n        height: 4rem;\r\n        border-bottom: 1px solid rgba(0, 0, 0, 0.1);\r\n      	font-weight: 700;\r\n      	font-size: 2rem;\r\n    }\r\n    .bx-splash {\r\n        position: relative;\r\n        display: -webkit-flex;\r\n        display: flex;\r\n      	-webkit-align-items: center;\r\n        align-items: center;\r\n      	min-height: 100vh;\r\n    }\r\n    .bx-spl-preload {\r\n        position: absolute;\r\n\r\n        top: 0px;\r\n        left: 0px;\r\n        width: 1px;\r\n        height: 1px;\r\n\r\n        overflow: hidden;\r\n    }\r\n    .bx-spl-line {\r\n      	position: relative;\r\n        display: -webkit-flex;\r\n        display: flex;\r\n        -webkit-align-items: stretch;\r\n        align-items: stretch;\r\n    }\r\n  	.bx-media-phone .bx-spl-line {\r\n      	-webkit-flex-direction: column;\r\n      	flex-direction: column;\r\n    }\r\n  	.bx-spl-cell {\r\n      	position: relative;\r\n  	}\r\n  	.bx-media-phone .bx-spl-cell {\r\n      	-webkit-basis: 100% !important; \r\n      	flex-basis: 100% !important;\r\n      	width: 100% !important;\r\n  	}\r\n    .bx-spl-line.bx-spl-l1 .bx-spl-cell {\r\n      	display: -webkit-flex;\r\n        display: flex;\r\n        -webkit-align-items: center;\r\n        align-items: center;\r\n    }\r\n  	.bx-spl-line.bx-spl-l1 .bx-spl-cell.bx-spl-c1 {\r\n        -webkit-flex: 1 1 70%; \r\n        flex:  1 1 70%;\r\n      	width: 70%;\r\n    }\r\n  	.bx-media-phone .bx-spl-line.bx-spl-l1 .bx-spl-cell.bx-spl-c1 {\r\n      	text-align: center;\r\n  	}\r\n  	.bx-spl-line.bx-spl-l1 .bx-spl-cell.bx-spl-c2 {\r\n        -webkit-flex: 0 0 30%; \r\n        flex:  0 1 30%;\r\n      	-webkit-justify-content: center;\r\n        justify-content: center;\r\n      	width: 30%;\r\n    }\r\n    .bx-spl-line.bx-spl-l1 .bx-spl-image {\r\n      	max-width: 100%;\r\n    }\r\n    .bx-spl-line.bx-spl-l2 .bx-spl-cell {\r\n        -webkit-flex: 1 1 33%; \r\n        flex:  1 1 33%;\r\n      	width: 33%;\r\n    }\r\n  	.bx-media-phone .bx-spl-line.bx-spl-l2 .bx-spl-cell {\r\n      	text-align: center;\r\n  	}\r\n    .bx-spl-line.bx-spl-l2 .bx-spl-cicon {\r\n		position: relative;\r\n      	display: -webkit-flex;\r\n        display: flex;\r\n        -webkit-align-items: flex-start;\r\n        align-items: flex-start;\r\n      	justify-content: flex-start;\r\n      	-webkit-justify-content: flex-start;\r\n    }\r\n    .bx-media-phone .bx-spl-line.bx-spl-l2 .bx-spl-cicon {\r\n      	justify-content: center;\r\n      	-webkit-justify-content: center;\r\n    }\r\n    .bx-spl-line.bx-spl-l2 .bx-spl-cicon .animation {\r\n        width: 4.25rem;\r\n        height: 4.25rem;\r\n    }\r\n</style>\r\n<div class=\"bx-page bx-def-color-bg-page\">\r\n  <div class=\"bx-header\">__logo__</div>\r\n  <div class=\"bx-splash\">\r\n      <div class=\"bx-splash-cnt bx-def-page-width bx-def-centered bx-def-padding-leftright\">\r\n          <div class=\"bx-spl-preload\">\r\n            <img src=\"<bx_image_url:spl-image-main.svg />\">\r\n          </div>\r\n          <div class=\"bx-spl-line bx-spl-l1\">\r\n            <div class=\"bx-spl-cell bx-spl-c1\">\r\n              <div class=\"bx-spl-ccnt bx-def-padding\">\r\n                <div class=\"bx-spl-title bx-def-font-h1 bx-def-font-semibold\"><bx_text:_sys_txt_splash_title /></div>\r\n                <div class=\"bx-spl-slogan bx-def-padding-sec-top bx-def-padding-bottom bx-def-font-grayed\"><bx_text:_sys_txt_splash_slogan /></div>\r\n                <div class=\"bx-spl-image bx-def-padding-top\">\r\n                  <img class=\"bx-spl-image\" src=\"<bx_image_url:spl-image-main.svg />\" />\r\n                </div>\r\n              </div>\r\n            </div>\r\n            <div class=\"bx-spl-cell bx-spl-c2 bx-hide-when-logged-in\">\r\n              <div class=\"bx-spl-ccnt bx-def-padding\">__join_form_in_box__</div>\r\n            </div>\r\n          </div>\r\n          <div class=\"bx-spl-line bx-spl-l2 bx-def-padding\">\r\n            <div class=\"bx-spl-cell bx-spl-c1\">\r\n              <div class=\"bx-spl-ccnt bx-def-padding\">\r\n                <div class=\"bx-spl-cicon connect\"><div class=\"animation\"></div></div>\r\n                <div class=\"bx-spl-ctitle bx-def-padding-sec-topbottom bx-def-font-h2\"><bx_text:_sys_txt_splash_connect /></div>\r\n                <div class=\"bx-spl-ctext bx-def-font-grayed\"><bx_text:_sys_txt_splash_connect_text /></div>\r\n              </div>\r\n            </div>\r\n            <div class=\"bx-spl-cell bx-spl-c2\">\r\n              <div class=\"bx-spl-ccnt bx-def-padding\">\r\n                <div class=\"bx-spl-cicon share\"><div class=\"animation\"></div></div>\r\n                <div class=\"bx-spl-ctitle bx-def-padding-sec-topbottom bx-def-font-h2\"><bx_text:_sys_txt_splash_share /></div>\r\n                <div class=\"bx-spl-ctext bx-def-font-grayed\"><bx_text:_sys_txt_splash_share_text /></div>\r\n              </div>\r\n            </div>\r\n            <div class=\"bx-spl-cell bx-spl-c3\">\r\n              <div class=\"bx-spl-ccnt bx-def-padding\">\r\n                <div class=\"bx-spl-cicon create\"><div class=\"animation\"></div></div>\r\n                <div class=\"bx-spl-ctitle bx-def-padding-sec-topbottom bx-def-font-h2\"><bx_text:_sys_txt_splash_create /></div>\r\n                <div class=\"bx-spl-ctext bx-def-font-grayed\"><bx_text:_sys_txt_splash_create_text /></div>\r\n              </div>\r\n            </div>\r\n          </div>\r\n      </div>\r\n  </div>\r\n</div>\r\n<script>\r\n  var animConnect = bodymovin.loadAnimation({\r\n    container: $(\'.bx-spl-cicon.connect .animation\').get(0),\r\n    path: \'<bx_image_url:spl-icon-connect.json />\',\r\n    renderer: \'svg\',\r\n    loop: true,\r\n    autoplay: true,\r\n  });\r\n  var animShare = bodymovin.loadAnimation({\r\n    container: $(\'.bx-spl-cicon.share .animation\').get(0),\r\n    path: \'<bx_image_url:spl-icon-share.json />\',\r\n    renderer: \'svg\',\r\n    loop: true,\r\n    autoplay: true,\r\n  });\r\n  var animCreate = bodymovin.loadAnimation({\r\n    container: $(\'.bx-spl-cicon.create .animation\').get(0),\r\n    path: \'<bx_image_url:spl-icon-create.json />\',\r\n    renderer: \'svg\',\r\n    loop: true,\r\n    autoplay: true,\r\n  });\r\n</script>', '\r', '');

-- sys_accounts, sys_form_inputs, sys_form_display_inputs: news are not subscribed by default, the login form does not show Remember me
UPDATE `sys_form_inputs` SET `checked` = 0 WHERE `object` = 'sys_account' AND `module` = 'system' AND `name` = 'receive_news' AND `checked` = 1;
UPDATE `sys_form_display_inputs` SET `active` = 0 WHERE `display_name` = 'sys_login' AND `input_name` = 'rememberMe' AND `active` = 1;
UPDATE `sys_form_display_inputs` SET `active` = 0 WHERE `display_name` = 'sys_account_create' AND `input_name` = 'receive_news' AND `active` = 1;

