-- sys_menu_items
-- sys_menu_items has no unique key on the name, so each new item is added only when it is not there yet.
-- site menu: Log in and Sign up first, for guests on phones, Sign up the primary one; the logo is Home on phones; More goes last and About below the modules' items
INSERT INTO `sys_menu_items` (`set_name`, `module`, `name`, `title_system`, `title`, `link`, `onclick`, `target`, `icon`, `submenu_object`, `visible_for_levels`, `hidden_on`, `copyable`, `primary`, `order`) SELECT 'sys_site', 'system', 'login', '_sys_menu_item_title_system_login', '_sys_menu_item_title_login', 'page.php?i=login', '', '', 'sign-in-alt', '', 1, '6', 0, 0, 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM (SELECT 1 FROM `sys_menu_items` WHERE `set_name` = 'sys_site' AND `module` = 'system' AND `name` = 'login') AS `existing`);
INSERT INTO `sys_menu_items` (`set_name`, `module`, `name`, `title_system`, `title`, `link`, `onclick`, `target`, `icon`, `submenu_object`, `visible_for_levels`, `hidden_on`, `copyable`, `primary`, `order`) SELECT 'sys_site', 'system', 'create-account', '_sys_menu_item_title_system_join', '_sys_menu_item_title_join', 'page.php?i=create-account', '', '', 'user-plus', '', 1, '6', 0, 1, 2 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM (SELECT 1 FROM `sys_menu_items` WHERE `set_name` = 'sys_site' AND `module` = 'system' AND `name` = 'create-account') AS `existing`);
UPDATE `sys_menu_items` SET `hidden_on` = '1' WHERE `set_name` = 'sys_site' AND `module` = 'system' AND `name` = 'home' AND `hidden_on` = '';
UPDATE `sys_menu_items` SET `order` = 10010 WHERE `set_name` = 'sys_site' AND `module` = 'system' AND `name` = 'more-auto' AND `order` = 9999;
UPDATE `sys_menu_items` SET `order` = 9999 WHERE `set_name` = 'sys_site' AND `module` = 'system' AND `name` = 'about' AND `order` = 2;

-- footer menu
UPDATE `sys_menu_items` SET `link` = '', `onclick` = '', `order` = 4 WHERE `set_name` = 'sys_footer' AND `module` = 'system' AND `name` = 'copyright' AND `order` = 6;
UPDATE `sys_menu_items` SET `onclick` = 'bx_menu_popup(''sys_switch_language_popup'', this, {pointer: {flip: true}});', `order` = 5 WHERE `set_name` = 'sys_footer' AND `module` = 'system' AND `name` = 'switch_language' AND `order` = 4;
UPDATE `sys_menu_items` SET `order` = 6 WHERE `set_name` = 'sys_footer' AND `module` = 'system' AND `name` = 'switch_template' AND `order` = 5;
