INSERT INTO `sys_menu_items` (`set_name`, `module`, `name`, `title_system`, `title`, `link`, `onclick`, `target`, `icon`, `submenu_object`, `visible_for_levels`, `active`, `copyable`, `order`) SELECT 'sys_footer', 'system', 'sounds', '_sys_menu_item_title_system_sounds', '', 'javascript:void(0);', 'bx_menu_popup_inline(''#bx-menu-footer-sounds'', this, {pointer: {flip: true}});', '', 'volume-up', '', 2147483647, 1, 1, 8 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM (SELECT 1 FROM `sys_menu_items` WHERE `set_name` = 'sys_footer' AND `module` = 'system' AND `name` = 'sounds') AS `existing`);
