-- Home page splash block: only a site that still has the RC3 default gets the new one.
UPDATE `sys_pages_blocks` SET `content` = '<style>\r\n    /* Home page splash block, laid out like the NEO guest home. The shape colours follow the light and dark scheme. */\r\n    .bx-landing {\r\n        --bx-landing-muted: #e4e4e7;\r\n        --bx-landing-accent: #dbeafe;\r\n        --bx-landing-accent-fg: #1d4ed8;\r\n        --bx-landing-primary: #2563eb;\r\n        --bx-landing-title: #09090b;\r\n    }\r\n    .dark .bx-landing {\r\n        --bx-landing-muted: #3f3f46;\r\n        --bx-landing-accent: #172554;\r\n        --bx-landing-accent-fg: #60a5fa;\r\n        --bx-landing-title: #fafafa;\r\n    }\r\n    .bx-landing-main {\r\n        display: flex;\r\n        flex-direction: column;\r\n        align-items: center;\r\n        justify-content: center;\r\n        gap: 1.5rem;\r\n        box-sizing: border-box;\r\n        width: 100%;\r\n        max-width: 88rem;\r\n        margin: 0 auto;\r\n        padding: 1.5rem;\r\n    }\r\n    .bx-landing-intro {\r\n        display: flex;\r\n        flex: 1 1 auto;\r\n        flex-direction: column;\r\n        align-items: center;\r\n        gap: 1.5rem;\r\n        width: 100%;\r\n        text-align: center;\r\n    }\r\n    .bx-landing-art {\r\n        display: block;\r\n        width: 12rem;\r\n        height: 12rem;\r\n    }\r\n    /* Raw blocks style their content as an article (bx-def-vanilla-html). not-prose turns most of that off;\r\n       this undoes the rest, so the sign-in card looks as it does on the login page. */\r\n    .bx-def-vanilla-html .bx-landing a {\r\n        text-decoration-line: none;\r\n    }\r\n    .bx-def-vanilla-html .bx-landing h2 {\r\n        padding-bottom: 0;\r\n        border-bottom-width: 0;\r\n        font-size: inherit;\r\n    }\r\n    .bx-def-vanilla-html .bx-landing p {\r\n        margin: 0;\r\n    }\r\n    .bx-landing-muted { fill: var(--bx-landing-muted); }\r\n    .bx-landing-accent { fill: var(--bx-landing-accent); }\r\n    .bx-landing-accent-fg { fill: var(--bx-landing-accent-fg); }\r\n    .bx-landing-primary { fill: var(--bx-landing-primary); }\r\n    .bx-landing h2.bx-landing-title {\r\n        margin: 0;\r\n        color: var(--bx-landing-title);\r\n        font-size: 2.25rem;\r\n        font-weight: 700;\r\n        line-height: 1.1;\r\n        letter-spacing: -0.025em;\r\n        text-wrap: balance;\r\n    }\r\n    .bx-landing-text {\r\n        max-width: 48rem;\r\n        margin: 0;\r\n        font-size: 1rem;\r\n        line-height: 1.5;\r\n        text-wrap: pretty;\r\n    }\r\n    .bx-landing-auth {\r\n        flex: none;\r\n        width: 100%;\r\n        max-width: 24rem;\r\n    }\r\n    @media (min-width: 640px) {\r\n        .bx-landing h2.bx-landing-title { font-size: 3rem; }\r\n        .bx-landing-text { font-size: 1.125rem; }\r\n    }\r\n    @media (min-width: 1024px) {\r\n        .bx-landing-main {\r\n            flex-direction: row;\r\n            gap: 3rem;\r\n            padding: 3rem;\r\n        }\r\n        .bx-landing-intro {\r\n            align-items: flex-start;\r\n            text-align: start;\r\n        }\r\n    }\r\n</style>\r\n<div class="bx-landing not-prose">\r\n    <div class="bx-landing-main">\r\n        <div class="bx-landing-intro">\r\n            <svg class="bx-landing-art" viewBox="0 0 200 200" aria-hidden="true" focusable="false">\r\n                <path class="bx-landing-muted" d="M28 4H72A24 24 0 0 1 96 28V72A24 24 0 0 1 72 96H28A24 24 0 0 1 4 72V28A24 24 0 0 1 28 4Z" />\r\n                <path class="bx-landing-primary" d="M24 50a26 26 0 1 0 52 0a26 26 0 1 0 -52 0Z" />\r\n                <path class="bx-landing-accent" d="M104 96V4A92 92 0 0 1 196 96Z" />\r\n                <path class="bx-landing-accent-fg" d="M168 20a12 12 0 1 0 24 0a12 12 0 1 0 -24 0Z" />\r\n                <path class="bx-landing-accent-fg" d="M4 104A46 46 0 0 0 96 104Z" />\r\n                <path class="bx-landing-muted" d="M4 196A46 46 0 0 1 96 196Z" />\r\n                <path class="bx-landing-muted" d="M104 150a46 46 0 1 0 92 0a46 46 0 1 0 -92 0ZM120 150a30 30 0 1 0 60 0a30 30 0 1 0 -60 0Z" fill-rule="evenodd" />\r\n                <path class="bx-landing-primary" d="M134 150a16 16 0 1 0 32 0a16 16 0 1 0 -32 0Z" />\r\n            </svg>\r\n            <h2 class="bx-landing-title"><bx_text:_sys_txt_splash_title /></h2>\r\n            <p class="bx-landing-text bx-def-font-grayed"><bx_text:_sys_txt_splash_slogan /></p>\r\n        </div>\r\n        <div class="bx-landing-auth">__login_form_in_box__</div>\r\n    </div>\r\n</div>' WHERE `object` = 'sys_home' AND `module` = 'system' AND `title` = '_sys_page_block_title_homepage_splash' AND `type` = 'raw' AND REPLACE(`content`, '\r', '') = REPLACE('<style>\r\n    /*--- Splash ---*/\r\n  	.bx-page {\r\n        position: relative;\r\n  	}\r\n    .bx-splash-block {\r\n        position: relative;\r\n        display: -webkit-flex;\r\n        display: flex;\r\n      	-webkit-align-items: center;\r\n        align-items: center;\r\n    }\r\n    .bx-spl-preload {\r\n        position: absolute;\r\n\r\n        top: 0px;\r\n        left: 0px;\r\n        width: 1px;\r\n        height: 1px;\r\n\r\n        overflow: hidden;\r\n    }\r\n    .bx-spl-line {\r\n      	position: relative;\r\n        display: -webkit-flex;\r\n        display: flex;\r\n        -webkit-align-items: stretch;\r\n        align-items: stretch;\r\n    }\r\n  	.bx-media-phone .bx-spl-line {\r\n      	-webkit-flex-direction: column;\r\n      	flex-direction: column;\r\n    }\r\n  	.bx-spl-cell {\r\n      	position: relative;\r\n  	}\r\n  	.bx-media-phone .bx-spl-cell {\r\n      	-webkit-basis: 100% !important; \r\n      	flex-basis: 100% !important;\r\n      	width: 100% !important;\r\n  	}\r\n    .bx-spl-line.bx-spl-l1 .bx-spl-cell {\r\n      	display: -webkit-flex;\r\n        display: flex;\r\n        -webkit-align-items: center;\r\n        align-items: center;\r\n    }\r\n  	.bx-spl-line.bx-spl-l1 .bx-spl-cell.bx-spl-c1 {\r\n        -webkit-flex: 1 1 70%; \r\n        flex:  1 1 70%;\r\n      	width: 70%;\r\n    }\r\n  	.bx-media-phone .bx-spl-line.bx-spl-l1 .bx-spl-cell.bx-spl-c1 {\r\n      	text-align: center;\r\n  	}\r\n  	.bx-spl-line.bx-spl-l1 .bx-spl-cell.bx-spl-c2 {\r\n        -webkit-flex: 0 0 30%; \r\n        flex:  0 1 30%;\r\n      	-webkit-justify-content: center;\r\n        justify-content: center;\r\n      	width: 30%;\r\n    }\r\n    .bx-spl-line.bx-spl-l1 .bx-spl-image {\r\n      	max-width: 100%;\r\n    }\r\n    .bx-spl-line.bx-spl-l2 .bx-spl-cell {\r\n        -webkit-flex: 1 1 33%; \r\n        flex:  1 1 33%;\r\n      	width: 33%;\r\n    }\r\n  	.bx-media-phone .bx-spl-line.bx-spl-l2 .bx-spl-cell {\r\n      	text-align: center;\r\n  	}\r\n    .bx-spl-line.bx-spl-l2 .bx-spl-cicon {\r\n		position: relative;\r\n      	display: -webkit-flex;\r\n        display: flex;\r\n        -webkit-align-items: flex-start;\r\n        align-items: flex-start;\r\n      	justify-content: flex-start;\r\n      	-webkit-justify-content: flex-start;\r\n    }\r\n    .bx-media-phone .bx-spl-line.bx-spl-l2 .bx-spl-cicon {\r\n      	justify-content: center;\r\n      	-webkit-justify-content: center;\r\n    }\r\n    .bx-spl-line.bx-spl-l2 .bx-spl-cicon .animation {\r\n        width: 4.25rem;\r\n        height: 4.25rem;\r\n    }\r\n</style>\r\n<div class=\"bx-page bx-def-color-bg-page\">\r\n  <div class=\"bx-splash-block\">\r\n      <div class=\"bx-splash-cnt bx-def-page-width bx-def-centered bx-def-padding-leftright\">\r\n          <div class=\"bx-spl-preload\">\r\n            <img src=\"<bx_image_url:spl-image-main.svg />\">\r\n          </div>\r\n          <div class=\"bx-spl-line bx-spl-l1\">\r\n            <div class=\"bx-spl-cell bx-spl-c1\">\r\n              <div class=\"bx-spl-ccnt bx-def-padding\">\r\n                <div class=\"bx-spl-title bx-def-font-h1 bx-def-font-semibold\"><bx_text:_sys_txt_splash_title /></div>\r\n                <div class=\"bx-spl-slogan bx-def-padding-sec-top bx-def-padding-bottom bx-def-font-grayed\"><bx_text:_sys_txt_splas